'use strict';

//FormTree types
var types = {
	decision: require('./types/decision'),
	next: require('./types/next'),
	send: require('./types/send'),
	date: require('./types/date'),
	time: require('./types/time'),
	text: require('./types/text'),
	textarea: require('./types/textarea'),
	combo: require('./types/combo')
};

//FormTree subscribers
var subscribers = {
	validation: require('./subscribers/validation'),
	visibility: require('./subscribers/visibility')
};

//Validate validators
var validations = {
	'min-date': require('./validations/minDate')
};

var client;

function _setupClient(settings, context) {
	client = require('./client');

	client.setup({
		types: types,
		subscribers: subscribers,
		validations: validations
	}, settings, context);
}

function _addType(name, type) {
	types[name] = type;
}

function _addSubscriber(name, subscriber) {
	subscribers[name] = subscriber;
}

function _addValidation(name, validation) {
	validations[name] = validation;
}

function _render() {
	if (!client) {
		_setupClient();
	}
	client.render.apply(this, arguments);
}

function _read(item, value, name) {
	if(item && item.type){
		return types[item.type].read(item, value, name);
	}
}

module.exports = {
	addType: _addType,
	addSubscriber: _addSubscriber,
	addValidation: _addValidation,
	setupClient: _setupClient,
	render: _render,
	read: _read
};
